<script setup lang="ts">
import {ref,watch,computed} from 'vue'
import {rolesRequest} from '../composables/roles-api'
const props=defineProps<{identifier:string;tangent?:string;label:string;actorKey:string}>()
const scopeTangent=ref(props.tangent||''),chooseScope=ref(false),scopeActions=ref<string[]>([]),tangents=ref<{key:string;name:string}[]>([])
const open=ref(false),loading=ref(false),busy=ref(false),error=ref(''),action=ref(''),note=ref(''),duration=ref('86400'),customHours=ref(24),blockPosting=ref(true),blockStarting=ref(true)
const actions=ref<string[]>([])
const restriction=ref<{kind:string;until:string;reason:string;active:boolean}|null>(null)
const labels:Record<string,string>={warn:'Warn',timeout:'Time out',suspend:'Suspend',restore:'Restore',ban:'Ban from this Tangent',lift:'Lift restriction'}
const seconds=computed(()=>duration.value==='custom'?Math.round(customHours.value*3600):Number(duration.value))
const end=computed(()=>new Date(Date.now()+seconds.value*1000).toLocaleString())
let generation=0,mutationGeneration=0
async function load(){const current=++generation;loading.value=true;error.value='';try{const data=await rolesRequest<{actions:string[];scopeActions:string[];restriction:typeof restriction.value}>('/api/people/'+encodeURIComponent(props.identifier)+'/moderation'+(scopeTangent.value?'?tangent='+encodeURIComponent(scopeTangent.value):''));if(current===generation){actions.value=data.actions;scopeActions.value=data.scopeActions||[];restriction.value=data.restriction}}catch(cause){if(current===generation)error.value=(cause as Error).message}finally{if(current===generation)loading.value=false}}
watch(()=>props.actorKey+':'+props.identifier+':'+props.tangent,()=>{generation++;mutationGeneration++;busy.value=false;scopeTangent.value=props.tangent||'';chooseScope.value=false;scopeActions.value=[];open.value=false;action.value='';actions.value=[];restriction.value=null;error.value=''})
async function scopes(){chooseScope.value=true;try{const data=await rolesRequest<{tangents:{key:string;name:string;isOwner:boolean;membershipRole:string}[]}>('/api/v1/tangents');tangents.value=data.tangents.filter(item=>item.isOwner||item.membershipRole==='Admin')}catch(cause){error.value=(cause as Error).message}}
async function apply(){if(busy.value)return;const current=++mutationGeneration;busy.value=true;error.value='';try{await rolesRequest('/api/people/'+encodeURIComponent(props.identifier)+'/moderation',{method:'POST',body:{action:action.value,tangent:scopeTangent.value||undefined,note:note.value,durationSeconds:action.value==='timeout'?seconds.value:null,blockPosting:blockPosting.value,blockStarting:blockStarting.value}});if(current===mutationGeneration){action.value='';note.value='';await load()}}catch(cause){if(current===mutationGeneration)error.value=(cause as Error).message}finally{if(current===mutationGeneration)busy.value=false}}
</script>
<template><div class="participant-actions"><button class="btn btn-quiet" type="button" :aria-expanded="open" :aria-label="'Actions for '+label" @click="open=!open;open&&load()">•••</button><div v-if="open" class="participant-action-panel"><p v-if="loading" role="status">Checking permissions…</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="!loading&&!error&&!actions.length" class="hint">No moderation actions are available for this participant.</p><p v-if="restriction?.active" class="hint">{{restriction.kind==='Timeout'?'Time out until '+new Date(restriction.until).toLocaleString():'Banned from this Tangent'}} · {{restriction.reason}}</p><div v-if="!action" class="moderation-actions"><button v-if="!tangent&&scopeActions.length" class="btn btn-quiet" type="button" @click="scopes">Time out or ban in a Tangent…</button><a :href="'/u/'+encodeURIComponent(identifier)+'?tab=roles'">Profile and roles</a><button v-for="item in actions.filter(item=>item!=='lift'||restriction?.active)" :key="item" class="btn btn-quiet" :class="{'btn-danger':item==='ban'||item==='suspend'}" type="button" @click="action=item">{{labels[item]}}</button></div><label v-if="chooseScope">Tangent<select v-model="scopeTangent" class="input" @change="load"><option value="">Choose a Tangent</option><option v-for="item in tangents" :key="item.key" :value="item.key">{{item.name}}</option></select></label><form v-if="action" @submit.prevent="apply"><h3>{{labels[action]}} {{label}}</h3><p class="hint">{{action==='warn'?'An official warning, kept on their record.':action==='timeout'?'They can still read this Tangent.':action==='suspend'?'They cannot contribute anywhere until you restore them.':action==='ban'?'They cannot return to this Tangent until you lift the ban.':action==='restore'?'Restore their Space access under its current rules.':'The current restriction will end now.'}}</p><template v-if="action==='timeout'"><label>For how long<select v-model="duration" class="input"><option value="3600">1 hour</option><option value="86400">1 day</option><option value="604800">1 week</option><option value="custom">Custom</option></select></label><label v-if="duration==='custom'">Hours<input v-model.number="customHours" class="input" type="number" min="0.02" max="720" step="0.01" required></label><label class="check-row"><input v-model="blockPosting" type="checkbox">Post or reply</label><label class="check-row"><input v-model="blockStarting" type="checkbox">Start topics</label><p class="hint">Ends {{end}}. You can lift it sooner.</p></template><label>Note {{action==='warn'?'':'(optional)'}}<textarea v-model="note" class="input" rows="3" maxlength="280" :required="action==='warn'"></textarea></label><div class="form-actions"><button class="btn btn-primary" type="submit" :disabled="busy||(action==='timeout'&&!blockPosting&&!blockStarting)">{{busy?'Applying…':'Confirm '+labels[action]?.toLowerCase()}}</button><button class="btn btn-quiet" type="button" :disabled="busy" @click="action=''">Cancel</button></div></form></div></div></template>
